    { const vis = bub.style.display !== 'none' && cv.clientHeight > 0; st.bubB = vis ? (bub.getBoundingClientRect().bottom - cv.getBoundingClientRect().top) / cv.clientHeight * DESK_H : 0; }
    if (st.talking && performance.now() > st.talkEnd) st.talking = false;
